```javascript
const first = { name: "Ada", address: { city: "London" } };
const alias = first;
alias.name = "Grace";
console.log(first.name); // Grace

const shallowCopy = { ...first };
shallowCopy.name = "Lin";
shallowCopy.address.city = "New York";
console.log(first.name);         // Grace: outer object differs
console.log(first.address.city); // New York: nested object is shared
```
